window.SYLLABUS_CODE_FILES = {
  "./code/baselines/__init__.py": "\"\"\"Kho Baseline Cơ Bản Chia Nhỏ Theo Hàm (Modular Functions) & EDA Ngắn Gọn cho NLP.\"\"\"\n",
  "./code/baselines/basic_sentence_chunker.py": "\"\"\"Tách nhỏ các hàm Tách Câu, Gom Cụm Từ & Dịch Văn Bản Dài Cơ Bản.\"\"\"\nimport re\n\n\ndef split_sentences(text: str) -> list[str]:\n    return [s.strip() for s in re.split(r\"(?<=[.!?\\n])\\s+\", str(text).strip()) if s.strip()]\n\n\ndef pack_sentences(sentences: list[str], max_words: int = 180) -> list[str]:\n    chunks, cur, cur_words = [], [], 0\n    for s in sentences:\n        w = len(s.split())\n        if cur and cur_words + w > max_words:\n            chunks.append(\" \".join(cur))\n            cur, cur_words = [s], w\n        else:\n            cur.append(s)\n            cur_words += w\n    if cur:\n        chunks.append(\" \".join(cur))\n    return chunks\n\n\ndef split_long_text(text: str, max_words: int = 180) -> list[str]:\n    return pack_sentences(split_sentences(text), max_words=max_words)\n\n\ndef translate_long_text(text: str, batch_translate_fn, max_words: int = 180) -> str:\n    chunks = split_long_text(text, max_words=max_words)\n    return \" \".join(batch_translate_fn(chunks)) if chunks else \"\"\n",
  "./code/baselines/custom_meanpool_head.py": "\"\"\"Tách riêng hàm Masked Mean Pooling, lớp MeanPoolClassifier & hàm lọc câu sai tự tin cao.\"\"\"\nimport numpy as np\nimport torch\nimport torch.nn as nn\nfrom sklearn.metrics import classification_report\nfrom transformers import AutoConfig, AutoModel\n\n\ndef masked_mean_pooling(hidden: torch.Tensor, attention_mask: torch.Tensor) -> torch.Tensor:\n    m = attention_mask.unsqueeze(-1).float()\n    return (hidden * m).sum(dim=1) / m.sum(dim=1).clamp(min=1e-6)\n\n\nclass MeanPoolClassifier(nn.Module):\n    def __init__(self, model_name: str, num_classes: int):\n        super().__init__()\n        cfg = AutoConfig.from_pretrained(model_name)\n        self.encoder = AutoModel.from_pretrained(model_name, config=cfg)\n        self.fc = nn.Linear(cfg.hidden_size, num_classes)\n\n    def forward(self, input_ids: torch.Tensor, attention_mask: torch.Tensor, **kwargs) -> torch.Tensor:\n        h = self.encoder(input_ids=input_ids, attention_mask=attention_mask).last_hidden_state\n        return self.fc(masked_mean_pooling(h, attention_mask))\n\n\ndef find_top_wrong_samples(texts: list[str], y_true: list[int], probs: np.ndarray, top_k: int = 5) -> list[dict]:\n    preds, conf = probs.argmax(axis=1), probs.max(axis=1)\n    wrong = sorted([i for i in range(len(y_true)) if preds[i] != y_true[i]], key=lambda i: conf[i], reverse=True)\n    return [{\"text\": texts[i][:120], \"true\": int(y_true[i]), \"pred\": int(preds[i]), \"conf\": round(float(conf[i]), 4)} for i in wrong[:top_k]]\n\n\ndef quick_cls_report(y_true: list[int], y_pred: list[int], names: list[str] | None = None) -> str:\n    rep = classification_report(y_true, y_pred, target_names=names, digits=4, zero_division=0)\n    print(rep)\n    return rep\n",
  "./code/baselines/ner_bio_span_decoder.py": "\"\"\"Tách nhỏ các hàm phân tách nhãn BIO, gom thực thể (Span) & tính điểm Strict Span-F1.\"\"\"\n\n\ndef parse_bio_tag(tag: str) -> tuple[str, str]:\n    if \"-\" in tag:\n        prefix, ent = tag.split(\"-\", 1)\n        return prefix, ent\n    return \"O\", \"\"\n\n\ndef decode_bio_spans(tags: list[str]) -> set[tuple[str, int, int]]:\n    spans, cur_type, start = set(), None, -1\n    for i, tag in enumerate(tags):\n        prefix, ent = parse_bio_tag(tag)\n        if prefix == \"B\":\n            if cur_type:\n                spans.add((cur_type, start, i - 1))\n            cur_type, start = ent, i\n        elif prefix == \"I\":\n            if cur_type != ent:\n                if cur_type:\n                    spans.add((cur_type, start, i - 1))\n                cur_type, start = ent, i\n        elif cur_type:\n            spans.add((cur_type, start, i - 1))\n            cur_type, start = None, -1\n    if cur_type:\n        spans.add((cur_type, start, len(tags) - 1))\n    return spans\n\n\ndef count_span_overlap(pred_spans: set, gold_spans: set) -> tuple[int, int, int]:\n    return len(pred_spans & gold_spans), len(pred_spans - gold_spans), len(gold_spans - pred_spans)\n\n\ndef compute_strict_span_f1(pred_seqs: list[list[str]], gold_seqs: list[list[str]]) -> float:\n    tp = fp = fn = 0\n    for p, g in zip(pred_seqs, gold_seqs):\n        t_i, f_p, f_n = count_span_overlap(decode_bio_spans(p), decode_bio_spans(g))\n        tp, fp, fn = tp + t_i, fp + f_p, fn + f_n\n    return round(100.0 * (2 * tp) / max(2 * tp + fp + fn, 1), 2)\n",
  "./code/baselines/ner_token_cls_baseline.py": "\"\"\"Baseline Gán Nhãn Token Chia Nhỏ Từng Hàm: EDA -> Align -100 -> Model -> Train/Val -> Predict.\"\"\"\nfrom collections import Counter\nimport numpy as np\nimport torch\nfrom sklearn.metrics import f1_score\nfrom torch.utils.data import Dataset\nfrom transformers import AutoModelForTokenClassification, DataCollatorForTokenClassification\n\n\ndef quick_ner_eda(word_seqs: list[list[str]], tag_seqs: list[list[str]] | None = None) -> dict:\n    lens = [len(s) for s in word_seqs]\n    info = {\n        \"sentences\": len(word_seqs),\n        \"len_min_p50_p95_max\": (int(min(lens)), int(np.percentile(lens, 50)), int(np.percentile(lens, 95)), int(max(lens))) if lens else (),\n    }\n    if tag_seqs is not None:\n        info[\"entity_tags\"] = dict(Counter(t for seq in tag_seqs for t in seq if t != \"O\"))\n    print(\"[NER EDA]\", info)\n    return info\n\n\ndef align_word_labels(word_ids: list[int | None], word_tags: list[int]) -> list[int]:\n    \"\"\"Gán nhãn thật cho mảnh đầu của từ và -100 cho token đặc biệt / mảnh nối đuôi.\"\"\"\n    aligned, prev_id = [], None\n    for wid in word_ids:\n        aligned.append(-100 if (wid is None or wid == prev_id) else int(word_tags[wid]))\n        prev_id = wid\n    return aligned\n\n\nclass TokenClsDataset(Dataset):\n    def __init__(self, word_seqs: list[list[str]], tag_ids: list[list[int]] | None, tokenizer, max_len: int = 256):\n        self.words, self.tags, self.tok, self.max_len = word_seqs, tag_ids, tokenizer, max_len\n\n    def __len__(self):\n        return len(self.words)\n\n    def __getitem__(self, idx):\n        enc = self.tok(self.words[idx], is_split_into_words=True, truncation=True, max_length=self.max_len)\n        if self.tags is not None:\n            enc[\"labels\"] = align_word_labels(enc.word_ids(), self.tags[idx])\n        return enc\n\n\ndef build_ner_baseline(model_name: str, tag_list: list[str], tokenizer):\n    model = AutoModelForTokenClassification.from_pretrained(model_name, num_labels=len(tag_list))\n    return model, DataCollatorForTokenClassification(tokenizer)\n\n\ndef train_ner_epoch(model, loader, optimizer, device: str) -> float:\n    model.train()\n    loss_sum = 0.0\n    for b in loader:\n        b = {k: v.to(device) for k, v in b.items()}\n        optimizer.zero_grad()\n        loss = model(**b).loss\n        loss.backward()\n        optimizer.step()\n        loss_sum += loss.item()\n    return loss_sum / max(len(loader), 1)\n\n\n@torch.no_grad()\ndef eval_ner_macro_f1(model, loader, device: str) -> tuple[float, float]:\n    model.eval()\n    loss_sum, preds, golds = 0.0, [], []\n    for b in loader:\n        b = {k: v.to(device) for k, v in b.items()}\n        out = model(**b)\n        loss_sum += out.loss.item()\n        p, y = out.logits.argmax(-1).cpu(), b[\"labels\"].cpu()\n        valid = y != -100\n        preds.extend(p[valid].tolist())\n        golds.extend(y[valid].tolist())\n    f1 = 100.0 * f1_score(golds, preds, average=\"macro\", zero_division=0)\n    return loss_sum / max(len(loader), 1), f1\n\n\n@torch.no_grad()\ndef predict_word_tags(model, words: list[str], tokenizer, id2tag: dict[int, str], device: str, max_len: int = 256) -> list[str]:\n    model.to(device).eval()\n    enc = tokenizer(words, is_split_into_words=True, truncation=True, max_length=max_len, return_tensors=\"pt\")\n    pred_ids = model(**{k: v.to(device) for k, v in enc.items()}).logits[0].argmax(-1).cpu().tolist()\n    out_tags, prev_id = [], None\n    for wid, pid in zip(enc.word_ids(batch_index=0), pred_ids):\n        if wid is not None and wid != prev_id:\n            out_tags.append(id2tag[pid])\n        prev_id = wid\n    return out_tags\n",
  "./code/baselines/nlp_tfidf_baseline.py": "\"\"\"Bộ hàm Làm Sạch, EDA Ngắn Gọn Đa Năng & Baseline TF-IDF Chia Nhỏ Từng Bước.\"\"\"\nfrom pathlib import Path\nimport re\nimport unicodedata\nimport numpy as np\nimport pandas as pd\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import accuracy_score, f1_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.pipeline import Pipeline\n\n\ndef clean_text(text: str) -> str:\n    return re.sub(r\"\\s+\", \" \", unicodedata.normalize(\"NFC\", str(text))).strip()\n\n\ndef quick_text_eda(df: pd.DataFrame, text_col: str = \"text\", label_col: str | None = \"label\") -> dict:\n    s = df[text_col].fillna(\"\").astype(str).map(clean_text)\n    lens = s.map(lambda x: len(x.split()))\n    info = {\n        \"rows\": len(df),\n        \"empty_or_null\": int((s == \"\").sum()),\n        \"duplicates\": int(s.duplicated().sum()),\n        \"words_min_p50_p95_max\": (int(lens.min()), int(np.percentile(lens, 50)), int(np.percentile(lens, 95)), int(lens.max())),\n    }\n    if label_col and label_col in df.columns:\n        info[\"label_counts\"] = df[label_col].value_counts().to_dict()\n    print(\"[NLP EDA]\", info)\n    return info\n\n\ndef split_stratified_text(df: pd.DataFrame, text_col: str = \"text\", label_col: str = \"label\", val_ratio: float = 0.2, seed: int = 42):\n    x_all = df[text_col].fillna(\"\").map(clean_text)\n    y_all = df[label_col]\n    return train_test_split(x_all, y_all, test_size=val_ratio, random_state=seed, stratify=y_all)\n\n\ndef build_tfidf_pipeline(max_features: int = 50000, seed: int = 42) -> Pipeline:\n    return Pipeline([\n        (\"tfidf\", TfidfVectorizer(ngram_range=(1, 2), max_features=max_features, sublinear_tf=True)),\n        (\"clf\", LogisticRegression(max_iter=1000, class_weight=\"balanced\", random_state=seed)),\n    ])\n\n\ndef eval_cls_metrics(y_true, y_pred) -> dict[str, float]:\n    metrics = {\n        \"acc\": round(100.0 * accuracy_score(y_true, y_pred), 2),\n        \"macro_f1\": round(100.0 * f1_score(y_true, y_pred, average=\"macro\", zero_division=0), 2),\n    }\n    print(\"[TF-IDF Val]\", metrics)\n    return metrics\n\n\ndef run_tfidf_baseline(train_df: pd.DataFrame, test_df: pd.DataFrame, text_col: str = \"text\", label_col: str = \"label\", id_col: str = \"id\", out_csv: str = \"./outputs/submission.csv\") -> pd.DataFrame:\n    x_tr, x_va, y_tr, y_va = split_stratified_text(train_df, text_col, label_col)\n    pipe = build_tfidf_pipeline()\n    pipe.fit(x_tr, y_tr)\n    eval_cls_metrics(y_va, pipe.predict(x_va))\n\n    preds = pipe.predict(test_df[text_col].fillna(\"\").map(clean_text))\n    Path(out_csv).parent.mkdir(parents=True, exist_ok=True)\n    sub = pd.DataFrame({id_col: test_df[id_col], label_col: preds})\n    sub.to_csv(out_csv, index=False)\n    return sub\n",
  "./code/baselines/nlp_vocab_bilstm_scratch.py": "\"\"\"Bộ hàm Xây Dựng Vocab, Đệm Chuỗi, Gộp Mặt Nạ & Mạng BiLSTM Cơ Bản.\"\"\"\nfrom collections import Counter\nimport torch\nimport torch.nn as nn\n\n\ndef tokenize_words(text: str) -> list[str]:\n    return text.lower().split()\n\n\ndef build_vocab(texts: list[str], max_vocab: int = 20000, min_freq: int = 2) -> dict[str, int]:\n    cnt = Counter(w for line in texts for w in tokenize_words(line))\n    vocab = {\"<pad>\": 0, \"<unk>\": 1}\n    for w, c in cnt.most_common(max_vocab):\n        if c >= min_freq and w not in vocab:\n            vocab[w] = len(vocab)\n    return vocab\n\n\ndef encode_and_pad(text: str, vocab: dict[str, int], max_len: int = 128) -> tuple[torch.Tensor, torch.Tensor]:\n    ids = [vocab.get(w, 1) for w in tokenize_words(text)[:max_len]]\n    mask = [1.0] * len(ids) + [0.0] * (max_len - len(ids))\n    ids = ids + [0] * (max_len - len(ids))\n    return torch.tensor(ids, dtype=torch.long), torch.tensor(mask, dtype=torch.float32)\n\n\ndef masked_mean_pool(seq_out: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:\n    m = mask.unsqueeze(-1).float()\n    return (seq_out * m).sum(dim=1) / m.sum(dim=1).clamp(min=1e-6)\n\n\nclass BiLSTMClassifier(nn.Module):\n    def __init__(self, vocab_size: int, num_classes: int, dim: int = 128):\n        super().__init__()\n        self.emb = nn.Embedding(vocab_size, dim, padding_idx=0)\n        self.lstm = nn.LSTM(dim, dim, bidirectional=True, batch_first=True)\n        self.fc = nn.Linear(dim * 2, num_classes)\n\n    def forward(self, input_ids: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:\n        out, _ = self.lstm(self.emb(input_ids))\n        return self.fc(masked_mean_pool(out, mask))\n",
  "./code/baselines/seq2seq_baseline.py": "\"\"\"Baseline Seq2Seq Chia Nhỏ Từng Hàm: EDA -> Dataset -> Train/Val -> Generate -> CSV.\"\"\"\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nimport torch\nfrom torch.utils.data import Dataset\nfrom transformers import AutoModelForSeq2SeqLM, DataCollatorForSeq2Seq\n\n\ndef quick_seq2seq_eda(src_texts: list[str], tgt_texts: list[str] | None = None) -> dict:\n    src_l = [len(str(s).split()) for s in src_texts]\n    info = {\"pairs\": len(src_texts), \"src_p50_p95_max\": (int(np.percentile(src_l, 50)), int(np.percentile(src_l, 95)), int(max(src_l)))}\n    if tgt_texts is not None:\n        tgt_l = [len(str(t).split()) for t in tgt_texts]\n        info[\"tgt_p50_p95_max\"] = (int(np.percentile(tgt_l, 50)), int(np.percentile(tgt_l, 95)), int(max(tgt_l)))\n    print(\"[Seq2Seq EDA]\", info)\n    return info\n\n\nclass Seq2SeqDataset(Dataset):\n    def __init__(self, src_texts: list[str], tgt_texts: list[str] | None, tokenizer, max_src: int = 256, max_tgt: int = 128):\n        self.src, self.tgt, self.tok, self.max_src, self.max_tgt = list(src_texts), tgt_texts, tokenizer, max_src, max_tgt\n\n    def __len__(self):\n        return len(self.src)\n\n    def __getitem__(self, idx):\n        item = self.tok(str(self.src[idx]), truncation=True, max_length=self.max_src)\n        if self.tgt is not None:\n            item[\"labels\"] = self.tok(text_target=str(self.tgt[idx]), truncation=True, max_length=self.max_tgt)[\"input_ids\"]\n        return item\n\n\ndef build_seq2seq_baseline(model_name: str, tokenizer):\n    model = AutoModelForSeq2SeqLM.from_pretrained(model_name)\n    collator = DataCollatorForSeq2Seq(tokenizer=tokenizer, model=model, label_pad_token_id=-100)\n    return model, collator\n\n\ndef train_seq2seq_epoch(model, loader, optimizer, device: str) -> float:\n    model.train()\n    loss_sum = 0.0\n    for b in loader:\n        b = {k: v.to(device) for k, v in b.items()}\n        optimizer.zero_grad()\n        loss = model(**b).loss\n        loss.backward()\n        optimizer.step()\n        loss_sum += loss.item()\n    return loss_sum / max(len(loader), 1)\n\n\n@torch.no_grad()\ndef eval_seq2seq_loss(model, loader, device: str) -> float:\n    model.eval()\n    loss_sum = sum(model(**{k: v.to(device) for k, v in b.items()}).loss.item() for b in loader)\n    return loss_sum / max(len(loader), 1)\n\n\ndef fit_seq2seq(model, tr_loader, va_loader, epochs: int = 5, lr: float = 3e-5, device: str = \"cuda\", ckpt_path: str = \"best_seq2seq.pth\") -> float:\n    model.to(device)\n    opt = torch.optim.AdamW(model.parameters(), lr=lr, weight_decay=0.01)\n    best_loss = float(\"inf\")\n    for ep in range(1, epochs + 1):\n        tr_l = train_seq2seq_epoch(model, tr_loader, opt, device)\n        va_l = eval_seq2seq_loss(model, va_loader, device)\n        print(f\"Epoch {ep:02d} | TrLoss: {tr_l:.4f} | VaLoss: {va_l:.4f}\")\n        if va_l < best_loss:\n            best_loss = va_l\n            torch.save(model.state_dict(), ckpt_path)\n    return best_loss\n\n\n@torch.no_grad()\ndef generate_texts(model, tokenizer, loader, device: str = \"cuda\", max_new_tokens: int = 128) -> list[str]:\n    model.to(device).eval()\n    preds = []\n    for b in loader:\n        gen = model.generate(input_ids=b[\"input_ids\"].to(device), attention_mask=b[\"attention_mask\"].to(device), max_new_tokens=max_new_tokens)\n        preds.extend(s.strip() for s in tokenizer.batch_decode(gen, skip_special_tokens=True))\n    return preds\n\n\ndef predict_seq2seq_csv(model, tokenizer, loader, ids: list, device: str = \"cuda\", max_new_tokens: int = 128, out_csv: str = \"./outputs/submission.csv\") -> pd.DataFrame:\n    preds = generate_texts(model, tokenizer, loader, device=device, max_new_tokens=max_new_tokens)\n    Path(out_csv).parent.mkdir(parents=True, exist_ok=True)\n    sub = pd.DataFrame({\"id\": ids, \"prediction\": preds})\n    sub.to_csv(out_csv, index=False)\n    return sub\n",
  "./code/baselines/text_cls_baseline.py": "\"\"\"Baseline Phân Loại Văn Bản Chia Nhỏ Từng Hàm: Loaders -> Weights -> Model -> Train/Val -> CSV.\"\"\"\nimport os\nfrom dataclasses import dataclass\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nimport torch\nimport torch.nn as nn\nfrom sklearn.metrics import f1_score\nfrom sklearn.model_selection import train_test_split\nfrom torch.utils.data import DataLoader, Dataset\nfrom transformers import AutoModelForSequenceClassification, AutoTokenizer, DataCollatorWithPadding\n\nos.environ.setdefault(\"HF_HOME\", \"/opt/hf_models\")\n\n\n@dataclass\nclass TextCFG:\n    SEED: int = 42\n    MODEL_NAME: str = \"xlm-roberta-base\"\n    MAX_LEN: int = 256\n    BATCH_SIZE: int = 16\n    EPOCHS: int = 4\n    LR: float = 2e-5\n    VAL_RATIO: float = 0.2\n    PATIENCE: int = 2\n    DEVICE: str = \"cuda\" if torch.cuda.is_available() else \"cpu\"\n\n\nclass TextDataset(Dataset):\n    def __init__(self, texts: list[str], labels: list[int] | None, tokenizer, max_len: int):\n        self.texts, self.labels, self.tok, self.max_len = list(texts), labels, tokenizer, max_len\n\n    def __len__(self):\n        return len(self.texts)\n\n    def __getitem__(self, idx):\n        item = self.tok(str(self.texts[idx]), truncation=True, max_length=self.max_len)\n        if self.labels is not None:\n            item[\"labels\"] = int(self.labels[idx])\n        return item\n\n\ndef get_text_dataloaders(train_df: pd.DataFrame, test_df: pd.DataFrame, cfg: TextCFG, text_col: str = \"text\", label_col: str = \"label\"):\n    tok = AutoTokenizer.from_pretrained(cfg.MODEL_NAME)\n    classes = sorted(train_df[label_col].unique().tolist())\n    c2i = {c: i for i, c in enumerate(classes)}\n    y_all = train_df[label_col].map(c2i).tolist()\n\n    tr_idx, va_idx = train_test_split(np.arange(len(train_df)), test_size=cfg.VAL_RATIO, random_state=cfg.SEED, stratify=y_all)\n    col = DataCollatorWithPadding(tok)\n    tr_loader = DataLoader(TextDataset(train_df[text_col].iloc[tr_idx], [y_all[i] for i in tr_idx], tok, cfg.MAX_LEN), batch_size=cfg.BATCH_SIZE, shuffle=True, collate_fn=col)\n    va_loader = DataLoader(TextDataset(train_df[text_col].iloc[va_idx], [y_all[i] for i in va_idx], tok, cfg.MAX_LEN), batch_size=cfg.BATCH_SIZE * 2, collate_fn=col)\n    te_loader = DataLoader(TextDataset(test_df[text_col], None, tok, cfg.MAX_LEN), batch_size=cfg.BATCH_SIZE * 2, collate_fn=col)\n    return classes, y_all, tr_idx.tolist(), tr_loader, va_loader, te_loader\n\n\ndef get_class_weights(y_all: list[int], train_indices: list[int], num_classes: int, device: str) -> torch.Tensor:\n    counts = np.bincount([y_all[i] for i in train_indices], minlength=num_classes)\n    weights = len(train_indices) / (num_classes * np.maximum(counts, 1))\n    return torch.tensor(weights, dtype=torch.float32, device=device)\n\n\ndef build_text_classifier(model_name: str, num_classes: int):\n    return AutoModelForSequenceClassification.from_pretrained(model_name, num_labels=num_classes)\n\n\ndef train_one_epoch(model: nn.Module, loader, criterion, optimizer, device: str) -> float:\n    model.train()\n    loss_sum, total = 0.0, 0\n    for b in loader:\n        b = {k: v.to(device) for k, v in b.items()}\n        y = b.pop(\"labels\")\n        optimizer.zero_grad()\n        loss = criterion(model(**b).logits, y)\n        loss.backward()\n        optimizer.step()\n        loss_sum += loss.item() * y.size(0)\n        total += y.size(0)\n    return loss_sum / max(total, 1)\n\n\n@torch.no_grad()\ndef validate_text(model: nn.Module, loader, criterion, device: str) -> tuple[float, float, float]:\n    model.eval()\n    loss_sum, preds, golds = 0.0, [], []\n    for b in loader:\n        b = {k: v.to(device) for k, v in b.items()}\n        y = b.pop(\"labels\")\n        logits = model(**b).logits\n        loss_sum += criterion(logits, y).item() * y.size(0)\n        preds.extend(logits.argmax(-1).cpu().tolist())\n        golds.extend(y.cpu().tolist())\n    total = max(len(golds), 1)\n    acc = 100.0 * sum(p == g for p, g in zip(preds, golds)) / total\n    macro_f1 = 100.0 * f1_score(golds, preds, average=\"macro\", zero_division=0)\n    return loss_sum / total, acc, macro_f1\n\n\ndef fit_text(model: nn.Module, tr_loader, va_loader, criterion, cfg: TextCFG, ckpt_path: str = \"best_nlp.pth\") -> float:\n    model.to(cfg.DEVICE)\n    opt = torch.optim.AdamW(model.parameters(), lr=cfg.LR, weight_decay=0.01)\n    best_f1, wait = -1.0, 0\n    for ep in range(1, cfg.EPOCHS + 1):\n        tr_loss = train_one_epoch(model, tr_loader, criterion, opt, cfg.DEVICE)\n        va_loss, va_acc, va_f1 = validate_text(model, va_loader, criterion, cfg.DEVICE)\n        print(f\"Epoch {ep:02d} | TrLoss: {tr_loss:.4f} | VaLoss: {va_loss:.4f} | Acc: {va_acc:.2f}% | F1: {va_f1:.2f}%\")\n        if va_f1 > best_f1:\n            best_f1, wait = va_f1, 0\n            torch.save(model.state_dict(), ckpt_path)\n        else:\n            wait += 1\n            if wait >= cfg.PATIENCE:\n                break\n    return best_f1\n\n\n@torch.no_grad()\ndef predict_text_csv(model: nn.Module, te_loader, ids: list, classes: list, device: str, ckpt_path: str = \"best_nlp.pth\", out_csv: str = \"./outputs/submission.csv\") -> pd.DataFrame:\n    model.load_state_dict(torch.load(ckpt_path, map_location=device, weights_only=True))\n    model.to(device).eval()\n    preds = []\n    for b in te_loader:\n        preds.extend(model(**{k: v.to(device) for k, v in b.items()}).logits.argmax(-1).cpu().tolist())\n    Path(out_csv).parent.mkdir(parents=True, exist_ok=True)\n    sub = pd.DataFrame({\"id\": ids, \"label\": [classes[p] for p in preds]})\n    sub.to_csv(out_csv, index=False)\n    return sub\n",
  "./code/masternlp/__init__.py": "\"\"\"MasterNLP modular subpackage: masternlp.\"\"\"\n",
  "./code/masternlp/core/__init__.py": "\"\"\"MasterNLP modular subpackage: masternlp/core.\"\"\"\n",
  "./code/masternlp/core/pipeline.py": "from collections import Counter\nimport torch\nimport torch.nn as nn\n\ndef train_bpe_merges(texts: list[str], n_merges: int = 300) -> dict[tuple[int, int], int]:\n    \"\"\"Thuật toán BPE cốt lõi trong 11 dòng: lặp lại việc gộp cặp byte kề nhau xuất hiện nhiều nhất.\"\"\"\n    ids, merges = list(\" \".join(texts).encode(\"utf-8\")), {}\n    for step in range(n_merges):\n        counts = Counter(zip(ids, ids[1:]))\n        if not counts:\n            break\n        pair = counts.most_common(1)[0][0]\n        merges[pair], nxt, i = 256 + step, [], 0\n        while i < len(ids):\n            cond = i + 1 < len(ids) and (ids[i], ids[i + 1]) == pair\n            nxt.append(256 + step if cond else ids[i])\n            i += 2 if cond else 1\n        ids = nxt\n    return merges\n\ndef get_llrd_groups(model: nn.Module, lr: float = 2e-5, head_lr: float = 1e-4, decay: float = 0.9) -> list[dict]:\n    \"\"\"Layer-Wise LR Decay tổng quát cho mọi mạng BERT / RoBERTa / DeBERTa trong 10 dòng.\"\"\"\n    no_wd = (\"bias\", \"LayerNorm.weight\", \"layernorm.weight\")\n    max_l = max([int(s) for n in dict(model.named_parameters()) for s in n.split(\".\") if s.isdigit()] + [11]) + 1\n    groups = []\n    for name, p in model.named_parameters():\n        if p.requires_grad:\n            nums = [int(s) for s in name.split(\".\") if s.isdigit()]\n            cur_lr = head_lr if (\"classifier\" in name or \"head\" in name) else lr * (decay ** (max_l + 1 if \"embed\" in name else max_l - (nums[0] if nums else 0)))\n            groups.append({\"params\": [p], \"lr\": cur_lr, \"weight_decay\": 0.0 if any(k in name for k in no_wd) else 0.01})\n    return groups\n\ndef train_epoch(model: nn.Module, loader, optimizer, loss_fn, scheduler=None, device: str = \"cuda\") -> float:\n    \"\"\"Vòng lặp huấn luyện vạn năng 14 dòng: dùng chung cho Phân loại, Hồi quy, NER, QA, Retrieval & Seq2Seq.\"\"\"\n    model.train()\n    scaler = torch.amp.GradScaler(\"cuda\", enabled=(device == \"cuda\"))\n    total_loss = 0.0\n    for batch in loader:\n        batch = {k: (v.to(device) if torch.is_tensor(v) else v) for k, v in batch.items()}\n        optimizer.zero_grad(set_to_none=True)\n        with torch.amp.autocast(\"cuda\", enabled=(device == \"cuda\")):\n            loss = loss_fn(model, batch)\n        scaler.scale(loss).backward()\n        scaler.unscale_(optimizer)\n        nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n        scaler.step(optimizer)\n        scaler.update()\n        if scheduler is not None:\n            scheduler.step()\n        total_loss += loss.item()\n    return total_loss / max(1, len(loader))\n",
  "./code/masternlp/encoders/__init__.py": "\"\"\"MasterNLP modular subpackage: masternlp/encoders.\"\"\"\n",
  "./code/masternlp/encoders/lora_rope.py": "import math\nimport torch\nimport torch.nn as nn\n\nclass LoRALinear(nn.Module):\n    \"\"\"Thay thế hoàn toàn thư viện peft chỉ bằng 12 dòng PyTorch thuần: W' = W_0 + (alpha / r) * B @ A.\"\"\"\n    def __init__(self, base: nn.Linear, r: int = 8, alpha: float = 16.0):\n        super().__init__()\n        self.base, self.scale = base, alpha / r\n        self.base.requires_grad_(False)\n        self.lora_a = nn.Parameter(torch.empty(r, base.in_features))\n        self.lora_b = nn.Parameter(torch.zeros(base.out_features, r))\n        nn.init.kaiming_uniform_(self.lora_a, a=math.sqrt(5))\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        return self.base(x) + (x @ self.lora_a.to(x.dtype).T @ self.lora_b.to(x.dtype).T) * self.scale\n\ndef inject_lora(model: nn.Module, targets: tuple[str, ...] = (\"q_proj\", \"k_proj\", \"v_proj\", \"o_proj\"), r: int = 8) -> nn.Module:\n    \"\"\"Hàm đệ quy 8 dòng gắn LoRA vào BẤT KỲ mô hình nào trong transformers hoặc torchvision!\"\"\"\n    for name, child in list(model.named_children()):\n        if isinstance(child, nn.Linear) and any(t in name for t in targets):\n            setattr(model, name, LoRALinear(child, r=r, alpha=float(2 * r)))\n        else:\n            inject_lora(child, targets=targets, r=r)\n    return model\n\ndef apply_rope(x: torch.Tensor, pos: torch.Tensor, base: float = 10000.0) -> torch.Tensor:\n    \"\"\"Mã hóa vị trí quay RoPE trong 8 dòng: quay từng cặp chiều chẵn-lẻ góc m * theta_k.\"\"\"\n    half = x.size(-1) // 2\n    inv_f = 1.0 / (base ** (torch.arange(half, device=x.device, dtype=torch.float32) / half))\n    ang = pos.float().unsqueeze(-1) * inv_f\n    c, s = ang.cos().unsqueeze(1).type_as(x), ang.sin().unsqueeze(1).type_as(x)\n    xe, xo = x[..., 0::2], x[..., 1::2]\n    return torch.stack([xe * c - xo * s, xe * s + xo * c], dim=-1).flatten(-2)\n\ndef mask_prompt_labels(input_ids: torch.Tensor, prompt_lens: list[int]) -> torch.Tensor:\n    \"\"\"Gán -100 cho toàn bộ phần Prompt để LLM chỉ học sinh câu trả lời.\"\"\"\n    labels = input_ids.clone()\n    for i, plen in enumerate(prompt_lens):\n        labels[i, :plen] = -100\n    return labels\n",
  "./code/masternlp/encoders/mlm_mask.py": "import torch\n\ndef dynamic_mlm_mask(input_ids: torch.Tensor, special_ids: list[int],\n                     mask_id: int, vocab_size: int, prob: float = 0.15) -> tuple[torch.Tensor, torch.Tensor]:\n    \"\"\"Che mặt nạ động 80-10-10 chuẩn BERT trong 15 dòng (dùng khi tự dựng Transformer cho ngôn ngữ mật mã lạ).\"\"\"\n    x, labels = input_ids.clone(), input_ids.clone()\n    p_mat = torch.full_like(x, prob, dtype=torch.float32)\n    for sid in special_ids:\n        p_mat.masked_fill_(x == sid, 0.0)\n    masked = torch.bernoulli(p_mat).bool()\n    labels[~masked] = -100\n\n    rnd = torch.rand_like(p_mat)\n    x[masked & (rnd < 0.8)] = mask_id\n    rand_pos = masked & (rnd >= 0.8) & (rnd < 0.9)\n    x[rand_pos] = torch.randint(0, vocab_size, x.shape, device=x.device)[rand_pos]\n    return x, labels\n",
  "./code/masternlp/heads/__init__.py": "\"\"\"MasterNLP modular subpackage: masternlp/heads.\"\"\"\n",
  "./code/masternlp/heads/biaffine.py": "import torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nclass BiaffineSpanHead(nn.Module):\n    \"\"\"Ma trận đoạn Biaffine (i, j) trong 22 dòng — bắt trọn mọi thực thể lồng nhau với độ dài <= max_span.\"\"\"\n    def __init__(self, d_model: int, n_classes: int, proj: int = 192, max_span: int = 32):\n        super().__init__()\n        self.max_span = max_span\n        self.mlp_s = nn.Sequential(nn.Linear(d_model, proj), nn.GELU())\n        self.mlp_e = nn.Sequential(nn.Linear(d_model, proj), nn.GELU())\n        self.u_mat = nn.Parameter(torch.randn(n_classes, proj, proj) * 0.02)\n        self.w_lin = nn.Linear(proj * 2, n_classes)\n\n    def forward(self, h: torch.Tensor, mask: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:\n        hs, he, seq_len = self.mlp_s(h), self.mlp_e(h), h.size(1)\n        pair = torch.cat([hs.unsqueeze(2).expand(-1, -1, seq_len, -1), he.unsqueeze(1).expand(-1, seq_len, -1, -1)], -1)\n        logits = torch.einsum(\"bid,cdk,bjk->bijc\", hs, self.u_mat, he) + self.w_lin(pair)\n        idx = torch.arange(seq_len, device=h.device)\n        dist = idx[None, :] - idx[:, None]\n        valid = (dist >= 0) & (dist < self.max_span) & mask.bool()[:, :, None] & mask.bool()[:, None, :]\n        return logits, valid\n\ndef biaffine_span_loss(logits: torch.Tensor, gold_grid: torch.Tensor, valid: torch.Tensor) -> torch.Tensor:\n    return F.cross_entropy(logits[valid], gold_grid[valid])\n",
  "./code/masternlp/heads/crf.py": "import torch\nimport torch.nn as nn\n\nclass LinearChainCRF(nn.Module):\n    \"\"\"Linear-Chain CRF cô đọng trong 34 dòng: Forward Log-Sum-Exp + Giải mã quy hoạch động Viterbi.\"\"\"\n    def __init__(self, num_tags: int):\n        super().__init__()\n        self.start = nn.Parameter(torch.zeros(num_tags))\n        self.end = nn.Parameter(torch.zeros(num_tags))\n        self.trans = nn.Parameter(torch.zeros(num_tags, num_tags))\n\n    def forward(self, emit: torch.Tensor, tags: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:\n        b_sz, seq_len, _ = emit.shape\n        b_idx, safe_t = torch.arange(b_sz, device=emit.device), tags.clamp(min=0)\n        alpha = self.start + emit[:, 0]\n        gold = self.start[safe_t[:, 0]] + emit[b_idx, 0, safe_t[:, 0]]\n        for t in range(1, seq_len):\n            m = mask[:, t]\n            nxt = torch.logsumexp(alpha.unsqueeze(2) + self.trans + emit[:, t].unsqueeze(1), dim=1)\n            alpha = torch.where(m.unsqueeze(1), nxt, alpha)\n            gold = gold + (self.trans[safe_t[:, t - 1], safe_t[:, t]] + emit[b_idx, t, safe_t[:, t]]) * m.float()\n        log_z = torch.logsumexp(alpha + self.end, dim=1)\n        last_tag = safe_t[b_idx, mask.long().sum(1) - 1]\n        return (log_z - (gold + self.end[last_tag])).mean()\n\n    @torch.no_grad()\n    def decode(self, emit: torch.Tensor, mask: torch.Tensor) -> list[list[int]]:\n        v, ptrs = self.start + emit[:, 0], []\n        for t in range(1, emit.size(1)):\n            best_v, best_id = (v.unsqueeze(2) + self.trans).max(dim=1)\n            v = torch.where(mask[:, t].unsqueeze(1), best_v + emit[:, t], v)\n            ptrs.append(best_id)\n        last = (v + self.end).argmax(dim=1).tolist()\n        lens, out = mask.long().sum(1).tolist(), []\n        for b, cur in enumerate(last):\n            seq = [cur]\n            for t in range(lens[b] - 2, -1, -1):\n                cur = int(ptrs[t][b, cur])\n                seq.append(cur)\n            out.append(seq[::-1])\n        return out\n",
  "./code/masternlp/heads/pooler.py": "import torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nclass MaskPooler(nn.Module):\n    \"\"\"Bộ gộp đa năng (MeanMax / Attention + Pha trộn K tầng cuối), tự động che bỏ hoàn toàn vị trí [PAD].\"\"\"\n    def __init__(self, d_model: int, out_dim: int, mode: str = \"attn\", last_k: int = 4):\n        super().__init__()\n        self.mode, self.last_k = mode, last_k\n        self.layer_w = nn.Parameter(torch.zeros(last_k))\n        self.attn = nn.Sequential(nn.Linear(d_model, d_model // 2), nn.Tanh(), nn.Linear(d_model // 2, 1))\n        in_proj = d_model * 2 if mode == \"mean_max\" else d_model\n        self.fc = nn.Linear(in_proj, out_dim)\n\n    def forward(self, enc_out, attention_mask: torch.Tensor) -> torch.Tensor:\n        stack = torch.stack(enc_out.hidden_states[-self.last_k:], dim=0)\n        h = (F.softmax(self.layer_w, dim=0).view(-1, 1, 1, 1) * stack).sum(dim=0)\n        m = attention_mask.unsqueeze(-1).type_as(h)\n        if self.mode == \"mean_max\":\n            mean_v = (h * m).sum(1) / m.sum(1).clamp(min=1e-6)\n            max_v = h.masked_fill(m == 0, -1e4).max(1).values\n            feat = torch.cat([mean_v, max_v], dim=-1)\n        else:\n            w = F.softmax(self.attn(h).squeeze(-1).masked_fill(attention_mask == 0, -1e4), dim=-1)\n            feat = (w.unsqueeze(-1) * h).sum(1)\n        return self.fc(feat)\n",
  "./code/masternlp/heads/tuple_grid.py": "import torch\nimport torch.nn as nn\n\nclass PairGridHead(nn.Module):\n    \"\"\"Lưới quan hệ từ-đôi GTS O(L^2) trong 11 dòng — không bao giờ bịa từ nằm ngoài câu gốc.\"\"\"\n    def __init__(self, d_model: int, n_tags: int = 6):\n        super().__init__()\n        self.pa = nn.Linear(d_model, d_model // 2)\n        self.po = nn.Linear(d_model, d_model // 2)\n        self.clf = nn.Linear(d_model, n_tags)\n\n    def forward(self, h: torch.Tensor) -> torch.Tensor:\n        a, o, n = torch.relu(self.pa(h)), torch.relu(self.po(h)), h.size(1)\n        return self.clf(torch.cat([a[:, :, None, :].expand(-1, -1, n, -1), o[:, None, :, :].expand(-1, n, -1, -1)], -1))\n\ndef parse_tuples(text: str, tags: tuple[str, ...] = (\"[A]\", \"[C]\", \"[O]\", \"[S]\")) -> list[tuple[str, ...]]:\n    \"\"\"Bộ giải mã tổng quát an toàn khôi phục mọi cấu trúc Tuple từ chuỗi Seq2Seq, tự lọc phần tử lỗi.\"\"\"\n    out = []\n    for chunk in text.split(\";\"):\n        if all(t in chunk for t in tags):\n            vals, rem = [], chunk\n            for i, t in enumerate(tags):\n                _, rem = rem.split(t, 1)\n                if i + 1 < len(tags):\n                    val, rem = rem.split(tags[i + 1], 1)\n                    rem = tags[i + 1] + rem\n                    vals.append(val.strip())\n                else:\n                    vals.append(rem.strip())\n            out.append(tuple(vals))\n    return out\n",
  "./code/masternlp/inference/__init__.py": "\"\"\"MasterNLP modular subpackage: masternlp/inference.\"\"\"\n",
  "./code/masternlp/inference/char_ensemble.py": "import numpy as np\n\ndef char_span_ensemble(text_len: int, model_preds: list[tuple[np.ndarray, list[tuple[int, int]], float]],\n                       th: float = 0.5) -> list[tuple[int, int]]:\n    \"\"\"Hợp nhất xác suất cấp độ KÝ TỰ (20 dòng) giữa mọi kiến trúc khác bộ tách từ (DeBERTa + RoBERTa + PhoBERT).\"\"\"\n    p_sum = np.zeros(text_len, dtype=np.float64)\n    w_sum = np.zeros(text_len, dtype=np.float64)\n    for probs, offsets, weight in model_preds:\n        for p, (cs, ce) in zip(probs, offsets):\n            if ce > cs:\n                p_sum[max(0, cs) : min(text_len, ce)] += float(p) * weight\n                w_sum[max(0, cs) : min(text_len, ce)] += weight\n\n    mask = (p_sum / np.maximum(w_sum, 1e-8)) >= th\n    edges = np.flatnonzero(np.diff(np.r_[False, mask, False]))\n    return list(zip(edges[0::2].tolist(), edges[1::2].tolist()))\n",
  "./code/masternlp/inference/check_sub.py": "import numpy as np\nimport pandas as pd\n\ndef check_submission(sub: pd.DataFrame, sample: pd.DataFrame, target_cols: list[str], is_prob: bool = False) -> None:\n    \"\"\"Chốt chặn 15 dòng bắt trọn 6 lỗi gây 0 điểm oan trước khi nộp file cuối cùng trong phòng thi!\"\"\"\n    assert list(sub.columns) == list(sample.columns) and len(sub) == len(sample), \"Lệch cột hoặc số dòng!\"\n    assert (sub.iloc[:, 0].values == sample.iloc[:, 0].values).all(), \"Bị đảo thứ tự cột ID so với file mẫu!\"\n    for col in target_cols:\n        s = sub[col]\n        assert not s.isna().any(), f\"Cột {col} chứa NaN!\"\n        if np.issubdtype(s.dtype, np.number):\n            v = s.to_numpy(dtype=np.float64)\n            assert np.isfinite(v).all() and np.std(v) > 1e-7, f\"Cột {col} chứa Inf hoặc sụp đổ thành hằng số!\"\n            assert (not is_prob) or (v.min() >= 0.0 and v.max() <= 1.0), f\"Xác suất {col} vượt ngoài [0, 1]!\"\n        else:\n            assert (s.astype(str).str.strip() == \"\").mean() < 0.95, f\"Cột chuỗi {col} bị rỗng bất thường!\"\n",
  "./code/masternlp/inference/decoding.py": "import torch\nimport torch.nn.functional as F\n\n@torch.no_grad()\ndef beam_search_wu(step_fn, bos_id: int, eos_id: int, k: int = 4, max_len: int = 64, alpha: float = 0.8) -> list[int]:\n    \"\"\"Beam Search có chuẩn hóa độ dài ((5 + |Y|)/6)^alpha cô đọng trong 19 dòng dễ nhớ.\"\"\"\n    beams: list[tuple[list[int], float, bool]] = [([bos_id], 0.0, False)]\n    norm = lambda lp, n: lp / (((5.0 + n) / 6.0) ** alpha)\n    for _ in range(max_len):\n        cands = []\n        for seq, lp, done in beams:\n            if done:\n                cands.append((seq, lp, True))\n                continue\n            vals, ids = torch.topk(step_fn(torch.tensor([seq]))[0], k)\n            cands.extend((seq + [i], lp + v, i == eos_id) for v, i in zip(vals.tolist(), ids.tolist()))\n        beams = sorted(cands, key=lambda x: norm(x[1], len(x[0])), reverse=True)[:k]\n        if all(d for _, _, d in beams):\n            break\n    return beams[0][0]\n\ndef top_p_filter(logits: torch.Tensor, top_p: float = 0.9, temp: float = 0.8) -> torch.Tensor:\n    \"\"\"Nucleus Sampling (8 dòng): cắt bỏ đuôi phân phối xác suất thấp tránh sinh từ lạc đề.\"\"\"\n    z = logits / max(1e-5, temp)\n    s_val, s_idx = torch.sort(z, descending=True, dim=-1)\n    drop = torch.cumsum(F.softmax(s_val, dim=-1), dim=-1) > top_p\n    drop[..., 1:], drop[..., 0] = drop[..., :-1].clone(), False\n    mask = torch.zeros_like(z, dtype=torch.bool).scatter_(-1, s_idx, drop)\n    return z.masked_fill(mask, -1e9)\n",
  "./code/masternlp/inference/forensics_agent.py": "import ast\nfrom collections import Counter\nimport torch\nimport torch.nn.functional as F\n\n@torch.no_grad()\ndef llm_forensic_stats(logits: torch.Tensor, target_ids: torch.Tensor) -> dict[str, float]:\n    \"\"\"Đặc trưng pháp y Zero-Shot (Fast-DetectGPT): đo độ mượt bất thường & hạng xác suất token của văn bản AI.\"\"\"\n    lg, tg = logits[0, :-1], target_ids[0, 1:]\n    lp = F.log_softmax(lg, dim=-1)\n    p = lp.exp()\n    tok_lp = lp.gather(-1, tg.unsqueeze(-1)).squeeze(-1)\n    exp_lp = (p * lp).sum(-1)\n    var_lp = (p * (lp - exp_lp.unsqueeze(-1)).pow(2)).sum(-1)\n    ranks = (lg > lg.gather(-1, tg.unsqueeze(-1))).sum(-1) + 1\n    z_curv = float((tok_lp - exp_lp).mean() / var_lp.sqrt().mean().clamp(min=1e-5))\n    return {\"ppl\": float((-tok_lp.mean()).exp().clamp(max=1e4)), \"log_rank\": float(ranks.float().log().mean()), \"z_curv\": z_curv}\n\ndef safe_math_eval(expr: str) -> float | None:\n    \"\"\"Tính biểu thức toán học qua cây AST an toàn trong 12 dòng cho Tool-Integrated Reasoning Agent.\"\"\"\n    ops = {ast.Add: lambda a, b: a + b, ast.Sub: lambda a, b: a - b, ast.Mult: lambda a, b: a * b,\n           ast.Div: lambda a, b: a / b, ast.FloorDiv: lambda a, b: a // b, ast.Mod: lambda a, b: a % b, ast.Pow: lambda a, b: a ** b}\n    def _run(n):\n        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):\n            return float(n.value)\n        if isinstance(n, ast.UnaryOp) and isinstance(n.op, ast.USub):\n            return -_run(n.operand)\n        if isinstance(n, ast.BinOp) and type(n.op) in ops:\n            return ops[type(n.op)](_run(n.left), _run(n.right))\n        raise ValueError(\"Blocked\")\n    try:\n        return _run(ast.parse(expr.strip(), mode=\"eval\").body)\n    except Exception:\n        return None\n\ndef majority_vote(answers: list) -> object:\n    return Counter(a for a in answers if a is not None).most_common(1)[0][0]\n",
  "./code/masternlp/inference/qa_and_order.py": "import torch\nimport torch.nn.functional as F\n\ndef decode_qa_null_margin(s_log: torch.Tensor, e_log: torch.Tensor, ctx_mask: torch.Tensor,\n                          max_len: int = 30, margin: float = 0.0) -> tuple[int, int]:\n    \"\"\"Giải mã cặp (start, end) hợp lệ tối ưu kèm kiểm định vô nghiệm SQuAD v2 chỉ trong 12 dòng.\"\"\"\n    null_s = float(s_log[0] + e_log[0])\n    joint = s_log.masked_fill(~ctx_mask, -1e9)[:, None] + e_log.masked_fill(~ctx_mask, -1e9)[None, :]\n    idx = torch.arange(s_log.size(0), device=s_log.device)\n    valid = (idx[None, :] >= idx[:, None]) & ((idx[None, :] - idx[:, None]) < max_len)\n    joint = joint.masked_fill(~valid, -1e9)\n    flat = int(joint.view(-1).argmax())\n    bi, bj = divmod(flat, s_log.size(0))\n    return (0, 0) if (float(joint[bi, bj]) - null_s) < margin else (bi, bj)\n\ndef kendall_order_loss(pred: torch.Tensor, gold: torch.Tensor, alpha: float = 0.5, margin: float = 0.05) -> torch.Tensor:\n    \"\"\"Hàm mất mát kép L1 + Pairwise Ranking cho bài Sắp xếp thứ tự văn bản / mã nguồn (AI4Code & IOAI 2026).\"\"\"\n    dp, dg = pred[:, None] - pred[None, :], (gold[:, None] - gold[None, :] > 0).float()\n    pair_loss = (F.relu(margin - dp) * dg).sum() / dg.sum().clamp(min=1.0)\n    return F.l1_loss(pred, gold) + alpha * pair_loss\n",
  "./code/masternlp/inference/rag_guard.py": "import re\nimport torch\nimport torch.nn.functional as F\n\ndef structured_chunk(text: str, doc_title: str, max_words: int = 180, overlap: int = 35,\n                     split_pat: str = r\"\\n(?=(?:Điều\\s+\\d+|Section\\s+\\d+|#{1,3}\\s+))\") -> list[str]:\n    \"\"\"Phân mảnh tài liệu giữ nguyên tiêu đề phân cấp [Tài liệu | Điều/Mục] gắn vào đầu từng mảnh cắt.\"\"\"\n    chunks, step = [], max(1, max_words - overlap)\n    for sec in re.split(split_pat, text.strip()):\n        lines = [ln.strip() for ln in sec.splitlines() if ln.strip()]\n        if not lines:\n            continue\n        head, words = lines[0], \" \".join(lines[1:] or lines).split()\n        for s in range(0, len(words), step):\n            chunks.append(f\"[{doc_title} | {head}] {' '.join(words[s : s + max_words])}\")\n            if s + max_words >= len(words):\n                break\n    return chunks\n\n@torch.no_grad()\ndef nli_support_score(chunks: list[str], claim: str, tok, nli_model, entail_id: int = 0) -> float:\n    \"\"\"Trả về xác suất cao nhất mệnh đề claim được suy ra hợp lệ từ các đoạn bằng chứng (Chống ảo giác).\"\"\"\n    enc = tok(chunks, [claim] * len(chunks), padding=True, truncation=True, max_length=512, return_tensors=\"pt\")\n    probs = F.softmax(nli_model(**{k: v.to(nli_model.device) for k, v in enc.items()}).logits, dim=-1)\n    return float(probs[:, entail_id].max().item())\n",
  "./code/masternlp/inference/rrf.py": "def rrf_fuse(rank_lists: list[list[int]], weights: list[float] | None = None, k: int = 60, top_n: int = 50) -> list[int]:\n    \"\"\"Reciprocal Rank Fusion (9 dòng): hợp nhất BM25 và Dense KNN không phụ thuộc thang điểm tuyệt đối.\"\"\"\n    weights = weights or [1.0] * len(rank_lists)\n    scores: dict[int, float] = {}\n    for r_list, w in zip(rank_lists, weights):\n        for rank, doc_id in enumerate(r_list, start=1):\n            scores[doc_id] = scores.get(doc_id, 0.0) + w / (k + rank)\n    return [doc_id for doc_id, _ in sorted(scores.items(), key=lambda x: x[1], reverse=True)[:top_n]]\n\ndef clean_hard_negatives(pos_score: float, cand_ids: list[int], cand_scores: list[float],\n                         gold_ids: set[int], max_ratio: float = 0.92) -> list[int]:\n    \"\"\"Loại bỏ False Negatives (ứng viên chưa gán nhãn nhưng có điểm Cross-Encoder sát mẫu dương thật).\"\"\"\n    return [cid for cid, sc in zip(cand_ids, cand_scores) if cid not in gold_ids and sc < max_ratio * pos_score]\n",
  "./code/masternlp/inference/speed_qwk.py": "import random\nimport numpy as np\nfrom scipy.optimize import minimize\nfrom sklearn.metrics import cohen_kappa_score\nfrom torch.utils.data import Sampler\n\nclass LengthBatchSampler(Sampler):\n    \"\"\"Gom câu đồng độ dài cho vòng lặp PyTorch thuần trong 11 dòng — tăng tốc huấn luyện gấp 3x-4x.\"\"\"\n    def __init__(self, lengths: list[int], batch_size: int, shuffle: bool = True):\n        idx = sorted(range(len(lengths)), key=lengths.__getitem__)\n        self.batches = [idx[i : i + batch_size] for i in range(0, len(idx), batch_size)]\n        self.shuffle = shuffle\n\n    def __iter__(self):\n        b = list(self.batches)\n        if self.shuffle:\n            random.shuffle(b)\n        return iter(b)\n\n    def __len__(self) -> int:\n        return len(self.batches)\n\nclass QWKRounder:\n    \"\"\"Tối ưu điểm cắt liên tục -> điểm nguyên cho độ đo Quadratic Weighted Kappa trong 11 dòng.\"\"\"\n    def __init__(self, init_cuts: list[float]):\n        self.cuts = np.array(init_cuts, dtype=np.float64)\n\n    def fit(self, oof_pred: np.ndarray, y_true: np.ndarray) -> \"QWKRounder\":\n        loss = lambda c: -cohen_kappa_score(y_true, np.digitize(oof_pred, np.sort(c)), weights=\"quadratic\")\n        self.cuts = np.sort(minimize(loss, x0=self.cuts, method=\"Nelder-Mead\").x)\n        return self\n\n    def predict(self, pred: np.ndarray) -> np.ndarray:\n        return np.digitize(pred, self.cuts)\n",
  "./code/masternlp/inference/surgery.py": "import torch\nimport torch.nn as nn\n\ndef procrustes_svd(src_x: torch.Tensor, tgt_y: torch.Tensor) -> torch.Tensor:\n    \"\"\"Nghiệm đóng min_{Omega^T Omega = I} || X @ Omega - Y ||_F bằng SVD trong 5 dòng PyTorch.\"\"\"\n    xc = src_x - src_x.mean(0, keepdim=True)\n    yc = tgt_y - tgt_y.mean(0, keepdim=True)\n    u_mat, _, vh_mat = torch.linalg.svd(xc.T @ yc, full_matrices=False)\n    return u_mat @ vh_mat\n\ndef attach_steering_hook(layer: nn.Module, pos_acts: torch.Tensor, neg_acts: torch.Tensor, coeff: float = 1.5):\n    \"\"\"Contrastive Activation Addition (CAA): tiêm vector điều khiển hành vi vào Residual Stream trong 9 dòng.\"\"\"\n    vec = pos_acts.mean(0) - neg_acts.mean(0)\n    vec = vec / vec.norm(p=2).clamp(min=1e-8)\n    def _hook(mod, inp, out):\n        h = out[0] if isinstance(out, tuple) else out\n        steered = h + coeff * vec.to(h.device, h.dtype)\n        return (steered,) + out[1:] if isinstance(out, tuple) else steered\n    return layer.register_forward_hook(_hook)\n",
  "./code/masternlp/losses/__init__.py": "\"\"\"MasterNLP modular subpackage: masternlp/losses.\"\"\"\n",
  "./code/masternlp/losses/affect_fgm.py": "import torch\nimport torch.nn as nn\n\ndef ccc_loss(pred: torch.Tensor, target: torch.Tensor, eps: float = 1e-6) -> torch.Tensor:\n    \"\"\"Concordance Correlation Loss (7 dòng): giữ nguyên phương sai & tương quan cho bài toán chấm điểm / cảm xúc.\"\"\"\n    dp, dt = pred - pred.mean(0), target - target.mean(0)\n    cov = (dp * dt).mean(0)\n    ccc = (2.0 * cov) / ((dp ** 2).mean(0) + (dt ** 2).mean(0) + (pred.mean(0) - target.mean(0)) ** 2 + eps)\n    return (1.0 - ccc).mean()\n\ndef asymmetric_focal_loss(logits: torch.Tensor, targets: torch.Tensor,\n                          g_neg: float = 4.0, g_pos: float = 1.0, clip: float = 0.05) -> torch.Tensor:\n    \"\"\"Asymmetric Loss (8 dòng): triệt tiêu nhiễu từ hàng chục nhãn âm dễ mà không làm suy yếu nhãn dương hiếm.\"\"\"\n    p = torch.sigmoid(logits)\n    p_neg = (1.0 - p + clip).clamp(max=1.0)\n    log_loss = targets * p.clamp(min=1e-8).log() + (1.0 - targets) * p_neg.clamp(min=1e-8).log()\n    pt = targets * p + (1.0 - targets) * p_neg\n    w = (1.0 - pt).pow(g_pos * targets + g_neg * (1.0 - targets)).detach()\n    return -(w * log_loss).mean()\n\nclass FGMAttack:\n    \"\"\"Đối kháng Fast Gradient Method (12 dòng) trên Word Embeddings — tăng 0.005-0.015 điểm ổn định mọi đề NLP.\"\"\"\n    def __init__(self, model: nn.Module, eps: float = 0.5, key: str = \"word_embeddings\"):\n        self.model, self.eps, self.key, self.backup = model, eps, key, {}\n\n    def attack(self) -> None:\n        for name, p in self.model.named_parameters():\n            if p.requires_grad and self.key in name and p.grad is not None:\n                self.backup[name] = p.data.clone()\n                p.data.add_(self.eps * p.grad / p.grad.norm().clamp(min=1e-8))\n\n    def restore(self) -> None:\n        for name, p in self.model.named_parameters():\n            if name in self.backup:\n                p.data.copy_(self.backup.pop(name))\n",
  "./code/masternlp/losses/ctc_scratch.py": "import torch\n\ndef ctc_greedy_decode(token_ids: list[int], blank_id: int = 0) -> list[int]:\n    \"\"\"Ánh xạ gộp CTC B(pi) trong 4 dòng: gộp ký hiệu trùng liên tiếp trước -> lọc bỏ blank sau.\"\"\"\n    dedup = [tok for i, tok in enumerate(token_ids) if i == 0 or tok != token_ids[i - 1]]\n    return [tok for tok in dedup if tok != blank_id]\n\ndef ctc_forward_loss(log_probs: torch.Tensor, targets: torch.Tensor, blank_id: int = 0) -> torch.Tensor:\n    \"\"\"Quy hoạch động Forward CTC trên chuỗi mở rộng [blank, y1, blank, y2, ...] dài 2U + 1 (18 dòng).\"\"\"\n    t_steps, ext_len = log_probs.size(0), 2 * targets.numel() + 1\n    ext = torch.full((ext_len,), blank_id, dtype=torch.long, device=log_probs.device)\n    ext[1::2] = targets\n    alpha = torch.full((t_steps, ext_len), -1e9, device=log_probs.device)\n    alpha[0, 0] = log_probs[0, ext[0]]\n    if ext_len > 1:\n        alpha[0, 1] = log_probs[0, ext[1]]\n    for t in range(1, t_steps):\n        for s in range(ext_len):\n            prev = [alpha[t - 1, s]] + ([alpha[t - 1, s - 1]] if s > 0 else [])\n            if s > 1 and ext[s] != blank_id and ext[s] != ext[s - 2]:\n                prev.append(alpha[t - 1, s - 2])\n            alpha[t, s] = torch.logsumexp(torch.stack(prev), dim=0) + log_probs[t, ext[s]]\n    end_pair = alpha[-1, -1:] if ext_len == 1 else torch.stack([alpha[-1, -1], alpha[-1, -2]])\n    return -torch.logsumexp(end_pair, dim=0)\n",
  "./code/masternlp/losses/dpo.py": "import numpy as np\nimport torch\nimport torch.nn.functional as F\n\ndef seq_logprob(logits: torch.Tensor, labels: torch.Tensor) -> torch.Tensor:\n    \"\"\"Tính tổng log P(y | x) trên các token trả lời hợp lệ (bỏ qua vị trí -100) trong 5 dòng.\"\"\"\n    lg, lb = logits[:, :-1, :], labels[:, 1:]\n    mask = lb != -100\n    tok_lp = F.log_softmax(lg, dim=-1).gather(-1, lb.clamp(min=0).unsqueeze(-1)).squeeze(-1)\n    return (tok_lp * mask.float()).sum(dim=-1)\n\ndef dpo_loss(pi_win_lp: torch.Tensor, pi_lose_lp: torch.Tensor,\n             ref_win_lp: torch.Tensor, ref_lose_lp: torch.Tensor, beta: float = 0.1) -> torch.Tensor:\n    \"\"\"Nghiệm đóng Direct Preference Optimization (DPO) trong 3 dòng — không cần cài đặt thư viện trl!\"\"\"\n    margin = (pi_win_lp - ref_win_lp) - (pi_lose_lp - ref_lose_lp)\n    return -F.logsigmoid(beta * margin).mean()\n\ndef swap_order_debias(probs_ab: np.ndarray, probs_ba: np.ndarray) -> np.ndarray:\n    \"\"\"Khử thiên kiến vị trí A/B (cột 0: A thắng, cột 1: B thắng, cột 2: Hòa) chỉ bằng 1 dòng hoán vị.\"\"\"\n    return 0.5 * (probs_ab + probs_ba[:, [1, 0, 2]])\n",
  "./code/masternlp/losses/infonce.py": "import math\nfrom collections import Counter\nimport torch\nimport torch.nn.functional as F\n\nclass SimpleBM25:\n    \"\"\"Okapi BM25 tự viết trong 17 dòng Python thuần — cực nhanh, dễ nhớ và tùy biến tham số k1, b.\"\"\"\n    def __init__(self, docs: list[list[str]], k1: float = 1.5, b: float = 0.75):\n        self.k1, self.b, self.n = k1, b, len(docs)\n        self.lens = [len(d) for d in docs]\n        self.avgdl = sum(self.lens) / max(1, self.n)\n        self.tfs = [Counter(d) for d in docs]\n        df = Counter(t for tf in self.tfs for t in tf)\n        self.idf = {t: math.log(1.0 + (self.n - c + 0.5) / (c + 0.5)) for t, c in df.items()}\n\n    def score(self, query: list[str]) -> list[float]:\n        out = [0.0] * self.n\n        for t in query:\n            if t in self.idf:\n                for i, tf in enumerate(self.tfs):\n                    f = tf.get(t, 0)\n                    if f:\n                        out[i] += self.idf[t] * (f * (self.k1 + 1)) / (f + self.k1 * (1 - self.b + self.b * self.lens[i] / self.avgdl))\n        return out\n\ndef infonce_loss(q_emb: torch.Tensor, pos_emb: torch.Tensor, neg_emb: torch.Tensor | None = None, tau: float = 0.05) -> torch.Tensor:\n    \"\"\"Hàm mất mát đối tương phản SimCSE / DPR (7 dòng): trải đều vector lên mặt cầu đơn vị S^(d-1).\"\"\"\n    q, p = F.normalize(q_emb, dim=-1), F.normalize(pos_emb, dim=-1)\n    keys = torch.cat([p, F.normalize(neg_emb, dim=-1)], dim=0) if neg_emb is not None else p\n    return F.cross_entropy((q @ keys.T) / tau, torch.arange(q.size(0), device=q.device))\n",
  "./code/masternlp/losses/pcgrad.py": "import random\nimport torch\nimport torch.nn as nn\n\ndef pcgrad_step(task_losses: list[torch.Tensor], shared_params: list[nn.Parameter]) -> None:\n    \"\"\"Chiếu trực giao đạo hàm xung đột PCGrad trong 18 dòng — dùng cho mọi mạng Đa tác vụ (Multi-Task).\"\"\"\n    params = [p for p in shared_params if p.requires_grad]\n    grads = []\n    for k, loss in enumerate(task_losses):\n        gs = torch.autograd.grad(loss, params, retain_graph=(k < len(task_losses) - 1), allow_unused=True)\n        grads.append(torch.cat([(g.reshape(-1) if g is not None else torch.zeros_like(p).reshape(-1)) for g, p in zip(gs, params)]))\n\n    proj = [g.clone() for g in grads]\n    for i in range(len(grads)):\n        for j in random.sample(range(len(grads)), len(grads)):\n            dot = torch.dot(proj[i], grads[j])\n            if i != j and dot < 0:\n                proj[i] = proj[i] - (dot / grads[j].pow(2).sum().clamp(min=1e-12)) * grads[j]\n\n    merged, idx = torch.stack(proj).sum(0), 0\n    for p in params:\n        n = p.numel()\n        p.grad = merged[idx : idx + n].view_as(p).clone()\n        idx += n\n",
  "./code/masternlp/losses/rdrop_simcls.py": "import torch\nimport torch.nn.functional as F\n\ndef rdrop_kl_loss(logits_1: torch.Tensor, logits_2: torch.Tensor, mask: torch.Tensor | None = None) -> torch.Tensor:\n    \"\"\"Điều hòa R-Drop KL đối xứng trong 7 dòng — dùng được cho cả Phân loại, NER lẫn Seq2Seq!\"\"\"\n    lp1, lp2 = F.log_softmax(logits_1, dim=-1), F.log_softmax(logits_2, dim=-1)\n    kl = 0.5 * ((lp1.exp() * (lp1 - lp2)).sum(-1) + (lp2.exp() * (lp2 - lp1)).sum(-1))\n    return (kl * mask.float()).sum() / mask.float().sum().clamp(min=1.0) if mask is not None else kl.mean()\n\ndef simcls_ranking_loss(doc_v: torch.Tensor, gold_v: torch.Tensor, cand_vs: torch.Tensor, margin: float = 0.01) -> torch.Tensor:\n    \"\"\"SimCLS vector hóa 10 dòng (không vòng lặp!): xếp hạng ứng viên cand_vs [B, K, D] theo đúng thứ tự ROUGE.\"\"\"\n    d = F.normalize(doc_v, dim=-1).unsqueeze(1)\n    g_sim = (d * F.normalize(gold_v, dim=-1).unsqueeze(1)).sum(-1)\n    c_sim = (d * F.normalize(cand_vs, dim=-1)).sum(-1)\n    k = c_sim.size(1)\n    idx = torch.arange(k, device=c_sim.device)\n    rank_gap = (idx[None, :] - idx[:, None]).clamp(min=0).float() * margin\n    pair_mat = F.relu(c_sim[:, None, :] - c_sim[:, :, None] + rank_gap[None, :, :])\n    tri_mask = idx[None, :] > idx[:, None]\n    return F.relu(c_sim - g_sim).mean() + pair_mat[:, tri_mask].mean()\n",
  "./code/masternlp/losses/robust_ood.py": "import torch\n\nHOMOGLYPH_TABLE = str.maketrans({\n    \"а\": \"a\", \"е\": \"e\", \"о\": \"o\", \"р\": \"p\", \"с\": \"c\", \"у\": \"y\", \"х\": \"x\",\n    \"А\": \"A\", \"В\": \"B\", \"Е\": \"E\", \"К\": \"K\", \"М\": \"M\", \"Н\": \"H\", \"О\": \"O\", \"Р\": \"P\", \"С\": \"C\", \"Т\": \"T\", \"Х\": \"X\",\n})\n\ndef clean_homoglyphs(text: str) -> str:\n    \"\"\"Bảo toàn 100% độ dài chuỗi ký tự (an toàn tuyệt đối cho cả bài chấm vị trí NER/QA).\"\"\"\n    return text.translate(HOMOGLYPH_TABLE)\n\ndef deep_coral_loss(src_h: torch.Tensor, tgt_h: torch.Tensor) -> torch.Tensor:\n    \"\"\"Căn chỉnh hiệp phương sai bậc hai giữa miền Train có nhãn và miền Test không nhãn trong 5 dòng.\"\"\"\n    sc, tc = src_h - src_h.mean(0, keepdim=True), tgt_h - tgt_h.mean(0, keepdim=True)\n    cs = (sc.T @ sc) / max(1, src_h.size(0) - 1)\n    ct = (tc.T @ tc) / max(1, tgt_h.size(0) - 1)\n    return ((cs - ct) ** 2).mean() / 4.0\n\ndef free_energy_ood(logits: torch.Tensor, temp: float = 1.0) -> torch.Tensor:\n    \"\"\"Điểm năng lượng tự do 1 dòng: giá trị càng lớn càng chắc chắn mẫu nằm ngoài phân phối đã học.\"\"\"\n    return -temp * torch.logsumexp(logits / temp, dim=-1)\n",
  "./code/package_tree.txt": "baselines/                        # Kho Baseline NLP cơ bản tối giản & EDA chữ đa năng (0 dòng vẽ biểu đồ)\n├── nlp_tfidf_baseline.py         # quick_text_eda() cho mọi bài NLP & TF-IDF + LogisticRegression (5 giây)\n├── nlp_vocab_bilstm_scratch.py   # Tự xây Vocab, Padding & mạng BiLSTM tối giản bằng PyTorch thuần\n├── text_cls_baseline.py          # Phân loại văn bản khép kín A–Z: DynamicPad -> AutoModel -> submission.csv\n├── custom_meanpool_head.py       # MeanPoolClassifier cơ bản & báo cáo F1 từng lớp\n├── ner_token_cls_baseline.py     # quick_ner_eda() & TokenClsDataset căn chỉnh word_ids() -> -100\n├── ner_bio_span_decoder.py       # decode_bio_spans() & compute_strict_span_f1() cơ bản\n├── seq2seq_baseline.py           # quick_seq2seq_eda() & AutoModelForSeq2SeqLM -> submission.csv\n└── basic_sentence_chunker.py     # split_long_text() chia câu cơ bản cho tài liệu dài vượt max_src\n\nmasternlp/                        # Khung 5 tầng mô-đun nâng cao cho Giai đoạn 0–6 (100% thư viện chuẩn OlpAI'25)\n├── core/\n│   ├── pipeline.py               # get_llrd_groups() & train_epoch() tổng quát cho mọi tác vụ\n│   └── validation.py             # make_group_folds() chống rò rỉ văn bản gần trùng lặp\n├── encoders/                     # build_encoder(), dynamic_mlm_mask(), inject_lora(), apply_rope()\n├── heads/                        # MaskPooler, LinearChainCRF, BiaffineSpanHead, PairGridHead\n├── losses/                       # ccc_loss, asymmetric_focal_loss, FGMAttack, pcgrad_step, infonce_loss, dpo_loss\n└── inference/                    # tune_thresholds, rrf_fuse, char_span_ensemble, QWKRounder, check_submission\n",
  "./code/recipes/asr_scipy_lib.py": "import numpy as np\nimport torch.nn as nn\nfrom scipy.io import wavfile\nfrom scipy.signal import resample_poly, stft\nfrom transformers import AutoModelForCTC, AutoProcessor, WhisperForConditionalGeneration, WhisperProcessor\n\n# 1. Đọc WAV & Trích xuất phổ STFT bằng scipy chuẩn của OlpAI'25 (không cần cài đặt torchaudio!):\ndef load_wav_16k(path: str) -> tuple[np.ndarray, np.ndarray]:\n    sr, wav = wavfile.read(path)\n    wav = wav.astype(np.float32) / (32768.0 if wav.dtype == np.int16 else 1.0)\n    if wav.ndim > 1:\n        wav = wav.mean(axis=1)\n    if sr != 16000:\n        wav = resample_poly(wav, 16000, sr).astype(np.float32)\n    _, _, spec = stft(wav, fs=16000, nperseg=400, noverlap=240)\n    return wav, np.log1p(np.abs(spec))\n\n# 2. AutoProcessor của Wav2Vec2 & Whisper tự trích xuất đặc trưng âm thanh trực tiếp từ mảng NumPy 16kHz:\nctc_criterion = nn.CTCLoss(blank=0, zero_infinity=True)\nw2v_proc = AutoProcessor.from_pretrained(\"facebook/wav2vec2-base-960h\")\nw2v_net = AutoModelForCTC.from_pretrained(\"facebook/wav2vec2-base-960h\")\nwh_proc = WhisperProcessor.from_pretrained(\"openai/whisper-small\")\nwh_net = WhisperForConditionalGeneration.from_pretrained(\"openai/whisper-small\")\n",
  "./code/recipes/baseline_v0_lib.py": "import os, random\nimport numpy as np\nimport torch\nfrom scipy.sparse.csgraph import connected_components\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import RidgeClassifier\nfrom sklearn.model_selection import StratifiedGroupKFold\nfrom transformers import AutoModelForSequenceClassification, AutoTokenizer, DataCollatorWithPadding\n\ndef seed_all(seed: int = 42) -> None:\n    random.seed(seed)\n    os.environ[\"PYTHONHASHSEED\"] = str(seed)\n    np.random.seed(seed)\n    torch.manual_seed(seed)\n    torch.cuda.manual_seed_all(seed)\n\ndef make_group_folds(texts: list[str], y: np.ndarray, n_splits: int = 5, sim_th: float = 0.88) -> np.ndarray:\n    \"\"\"Gom cụm văn bản gần trùng lặp bằng char n-gram TF-IDF + Đồ thị liên thông trước khi chia Fold.\"\"\"\n    mat = TfidfVectorizer(analyzer=\"char_wb\", ngram_range=(3, 5), min_df=2).fit_transform(texts)\n    _, groups = connected_components((mat @ mat.T) >= sim_th, directed=False)\n    folds = np.zeros(len(texts), dtype=int)\n    sgkf = StratifiedGroupKFold(n_splits=n_splits, shuffle=True, random_state=42)\n    for f, (_, val_idx) in enumerate(sgkf.split(texts, y, groups)):\n        folds[val_idx] = f\n    return folds\n\n# 1. Baseline v0.1 trong 5 giây (kiểm chứng luồng dữ liệu & metric):\ntfidf = TfidfVectorizer(ngram_range=(1, 3), sublinear_tf=True, max_features=60000)\nfast_clf = RidgeClassifier(alpha=1.0)\n\n# 2. Huấn luyện bộ tách từ BPE mới cho ngôn ngữ lạ (IOAI 2024) trực tiếp từ transformers (chỉ 1 dòng!):\n# custom_tok = AutoTokenizer.from_pretrained(\"gpt2\").train_new_from_iterator(texts, vocab_size=8000)\n\n# 3. Baseline v0.2 Neural chuẩn mực với Dynamic Padding (nhanh gấp 4 lần đệm tĩnh):\ntok = AutoTokenizer.from_pretrained(\"microsoft/deberta-v3-small\")\npad_collate = DataCollatorWithPadding(tok, pad_to_multiple_of=8)\nmodel_v0 = AutoModelForSequenceClassification.from_pretrained(\"microsoft/deberta-v3-small\", num_labels=2)\n",
  "./code/recipes/blending_xgb_lib.py": "import numpy as np\nfrom scipy.special import expit, logit\nfrom scipy.stats import rankdata\nfrom xgboost import XGBClassifier\n\n# 1. Pha trộn Log-Odds (tối ưu cho Log-Loss) & Rank Percentile (tối ưu cho ROC-AUC / Spearman):\ndef blend_logit(probs: list[np.ndarray], weights: list[float]) -> np.ndarray:\n    return expit(sum(w * logit(np.clip(p, 1e-6, 1 - 1e-6)) for p, w in zip(probs, weights)))\n\ndef blend_rank(preds: list[np.ndarray], weights: list[float]) -> np.ndarray:\n    return sum(w * (rankdata(p) / len(p)) for p, w in zip(preds, weights))\n\n# 2. Meta-Stacker bằng XGBoost (có sẵn trong OlpAI'25) kết hợp OOF của TF-IDF + DeBERTa + XLM-R + thống kê độ dài:\nmeta_stacker = XGBClassifier(n_estimators=200, max_depth=3, learning_rate=0.03, subsample=0.8, random_state=42)\n",
  "./code/recipes/bm25_biencoder_lib.py": "import torch\nimport torch.nn.functional as F\nfrom gensim.corpora import Dictionary\nfrom gensim.models import OkapiBM25Model\nfrom gensim.similarities import SparseMatrixSimilarity\nfrom transformers import AutoModel, AutoTokenizer\n\n# 1. Chỉ mục từ khóa Okapi BM25 có sẵn trong thư viện chuẩn gensim của OlpAI'25:\ndef build_gensim_bm25(corpus_tokens: list[list[str]]):\n    dct = Dictionary(corpus_tokens)\n    bm25 = OkapiBM25Model(dictionary=dct, k1=1.5, b=0.75)\n    index = SparseMatrixSimilarity(bm25[list(map(dct.doc2bow, corpus_tokens))], num_docs=len(corpus_tokens), num_terms=len(dct))\n    return dct, bm25, index\n\n# 2. Bi-Encoder trích xuất vector câu chuẩn hóa L2 chỉ bằng transformers + torch (không cần sentence-transformers):\n@torch.no_grad()\ndef encode_texts(texts: list[str], tok, model, max_len: int = 256) -> torch.Tensor:\n    enc = tok(texts, padding=True, truncation=True, max_length=max_len, return_tensors=\"pt\").to(model.device)\n    h = model(**enc).last_hidden_state\n    m = enc[\"attention_mask\"].unsqueeze(-1).type_as(h)\n    return F.normalize((h * m).sum(1) / m.sum(1).clamp(min=1e-6), p=2, dim=-1)\n",
  "./code/recipes/distill_lib.py": "import torch\nimport torch.nn.functional as F\n\ndef distill_loss(student_logits: torch.Tensor, teacher_logits: torch.Tensor,\n                 labels: torch.Tensor, temp: float = 2.5, alpha: float = 0.7) -> torch.Tensor:\n    \"\"\"Chưng cất tri thức 6 dòng: nén dàn Ensemble đa mô hình xuống 1 mô hình suy luận nhanh.\"\"\"\n    kl = F.kl_div(F.log_softmax(student_logits / temp, dim=-1), F.softmax(teacher_logits / temp, dim=-1), reduction=\"batchmean\")\n    return alpha * (temp ** 2) * kl + (1.0 - alpha) * F.cross_entropy(student_logits, labels)\n",
  "./code/recipes/diverse_beam_lib.py": "from transformers import AutoModelForSeq2SeqLM, GenerationConfig\n\n# Sinh 16 ứng viên đa dạng bằng Diverse Beam Search có sẵn làm đầu vào cho bộ chấm điểm tương phản SimCLS:\ndiv_cfg = GenerationConfig(\n    num_beams=16, num_beam_groups=4, diversity_penalty=1.0,\n    num_return_sequences=16, max_new_tokens=128, no_repeat_ngram_size=3,\n)\ncand_gen = AutoModelForSeq2SeqLM.from_pretrained(\"facebook/bart-large-cnn\")\n",
  "./code/recipes/dpo_bt_lib.py": "import numpy as np\nfrom sklearn.linear_model import LogisticRegression\nfrom transformers import AutoModelForCausalLM, AutoTokenizer\n\n# 1. Tải cặp Policy LM và Reference LM (đóng băng) bằng trực tiếp transformers:\ntok = AutoTokenizer.from_pretrained(\"Qwen/Qwen2.5-0.5B-Instruct\")\npolicy_lm = AutoModelForCausalLM.from_pretrained(\"Qwen/Qwen2.5-0.5B-Instruct\")\nref_lm = AutoModelForCausalLM.from_pretrained(\"Qwen/Qwen2.5-0.5B-Instruct\").eval().requires_grad_(False)\n\n# 2. Ước lượng điểm sức mạnh Bradley-Terry từ bảng kết quả thắng/thua cặp bằng LogisticRegression chuẩn:\ndef fit_bradley_terry_scores(n_models: int, pairs: np.ndarray, a_wins: np.ndarray) -> np.ndarray:\n    x_mat = np.zeros((len(pairs), n_models))\n    x_mat[np.arange(len(pairs)), pairs[:, 0]] = 1.0\n    x_mat[np.arange(len(pairs)), pairs[:, 1]] = -1.0\n    return LogisticRegression(C=1.0, fit_intercept=False).fit(x_mat, a_wins).coef_[0]\n",
  "./code/recipes/encoder_lib.py": "from transformers import AutoConfig, AutoModel\n\ndef build_encoder(model_name: str = \"microsoft/deberta-v3-base\", zero_dropout: bool = False):\n    \"\"\"Khởi tạo bất kỳ Encoder nào (DeBERTa, PhoBERT, XLM-R); bật zero_dropout=True khi giải bài Hồi quy.\"\"\"\n    cfg = AutoConfig.from_pretrained(model_name, output_hidden_states=True)\n    if zero_dropout:\n        cfg.update({\"hidden_dropout_prob\": 0.0, \"attention_probs_dropout_prob\": 0.0})\n    return AutoModel.from_pretrained(model_name, config=cfg)\n",
  "./code/recipes/fast_trainer_lib.py": "from transformers import TrainingArguments\n\n# Bật gom nhóm theo độ dài tương đương sẵn có trong transformers (giảm 75% lượng đệm [PAD] thừa):\nfast_args = TrainingArguments(\n    output_dir=\"./contest_ckpt\", per_device_train_batch_size=16, per_device_eval_batch_size=32,\n    group_by_length=True, bf16=True, save_strategy=\"epoch\", report_to=\"none\",\n)\n",
  "./code/recipes/forensics_lib.py": "from sklearn.ensemble import VotingClassifier\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import SGDClassifier\nfrom sklearn.naive_bayes import MultinomialNB\nfrom transformers import AutoTokenizer\n\ndef build_subword_forensic_clf(train_texts: list[str], vocab_size: int = 30000):\n    \"\"\"Chiến thuật Top-1 Detect AI Text dùng 100% thư viện OlpAI'25 (transformers + sklearn).\"\"\"\n    sub_tok = AutoTokenizer.from_pretrained(\"gpt2\").train_new_from_iterator(train_texts, vocab_size=vocab_size)\n    tok_docs = [\" \".join(map(str, sub_tok.encode(t))) for t in train_texts]\n    vec = TfidfVectorizer(ngram_range=(3, 5), lowercase=False, sublinear_tf=True, token_pattern=r\"\\S+\")\n    clf = VotingClassifier(\n        [(\"nb\", MultinomialNB(alpha=0.02)), (\"sgd\", SGDClassifier(loss=\"modified_huber\", random_state=42))],\n        weights=[0.35, 0.65], voting=\"soft\",\n    )\n    return sub_tok, vec, vec.fit_transform(tok_docs), clf\n",
  "./code/recipes/knn_rerank_lib.py": "import numpy as np\nimport torch\nfrom sklearn.neighbors import NearestNeighbors\nfrom transformers import AutoModelForSequenceClassification, AutoTokenizer\n\n# 1. Truy xuất Top-K vector Cosine bằng NearestNeighbors của scikit-learn (thay thế hoàn toàn FAISS):\ndef build_knn_retriever(doc_vecs: np.ndarray, top_k: int = 50) -> NearestNeighbors:\n    return NearestNeighbors(n_neighbors=top_k, metric=\"cosine\", n_jobs=-1).fit(doc_vecs)\n\n# 2. Tái xếp hạng chú ý chéo (Cross-Encoder Reranker) bằng trực tiếp AutoModelForSequenceClassification:\n@torch.no_grad()\ndef cross_rerank(query: str, cand_docs: list[str], tok, clf_model) -> np.ndarray:\n    pairs = tok([query] * len(cand_docs), cand_docs, padding=True, truncation=True, max_length=512, return_tensors=\"pt\")\n    logits = clf_model(**{k: v.to(clf_model.device) for k, v in pairs.items()}).logits\n    return (logits[:, -1] if logits.ndim == 2 and logits.size(-1) > 1 else logits.squeeze(-1)).cpu().numpy()\n",
  "./code/recipes/llm_head_tune_lib.py": "import torch\nfrom transformers import AutoModelForSequenceClassification, AutoTokenizer\n\ndef load_efficient_llm_clf(model_name: str = \"Qwen/Qwen2.5-1.5B-Instruct\", num_labels: int = 3):\n    \"\"\"Tải LLM bằng transformers thuần (BF16 + Gradient Checkpointing + mở khóa Head & 2 tầng cuối).\"\"\"\n    tok = AutoTokenizer.from_pretrained(model_name)\n    tok.pad_token = tok.pad_token or tok.eos_token\n    net = AutoModelForSequenceClassification.from_pretrained(model_name, num_labels=num_labels, torch_dtype=torch.bfloat16)\n    net.config.pad_token_id = tok.pad_token_id\n    net.gradient_checkpointing_enable()\n    net.requires_grad_(False)\n    for name, p in net.named_parameters():\n        if any(k in name for k in (\"score\", \"classifier\", \"norm\", \"layers.26.\", \"layers.27.\")):\n            p.requires_grad = True\n    return tok, net\n",
  "./code/recipes/losses_lib.py": "import numpy as np\nimport torch\nimport torch.nn as nn\nfrom scipy.stats import spearmanr\n\ndef make_pos_weight(y_train: np.ndarray) -> torch.Tensor:\n    \"\"\"Tự động tính trọng số bù lệch nhãn dương/âm cho mọi bài toán Đa nhãn (BCEWithLogitsLoss).\"\"\"\n    pos = y_train.sum(axis=0).clip(min=1.0)\n    neg = len(y_train) - pos\n    return torch.tensor(np.clip(neg / pos, 1.0, 20.0), dtype=torch.float32)\n\nmultilabel_loss = nn.BCEWithLogitsLoss()\nreg_loss = nn.SmoothL1Loss(beta=0.5)\n\ndef mean_spearman(preds: np.ndarray, targets: np.ndarray) -> float:\n    vals = [spearmanr(preds[:, j], targets[:, j]).correlation for j in range(preds.shape[1])]\n    return float(np.nanmean(vals))\n",
  "./code/recipes/offset_bio_lib.py": "from transformers import AutoModelForTokenClassification, AutoTokenizer\n\ndef align_spans_to_bio(tok, text: str, spans: list[tuple[int, int, str]], label2id: dict[str, int], max_len: int = 512):\n    \"\"\"Căn chỉnh mọi danh sách khoảng ký tự (start, end, type) sang nhãn BIO chính xác tới từng byte.\"\"\"\n    enc = tok(text, return_offsets_mapping=True, truncation=True, max_length=max_len)\n    seq_ids, labels = enc.sequence_ids(0), []\n    for idx, (cs, ce) in enumerate(enc[\"offset_mapping\"]):\n        if seq_ids[idx] is None or cs == ce:\n            labels.append(-100)\n            continue\n        hit = next(((s, e, t) for s, e, t in spans if ce > s and cs < e), None)\n        labels.append(label2id[\"O\" if hit is None else f\"{'B' if cs <= hit[0] else 'I'}-{hit[2]}\"])\n    enc[\"labels\"] = labels\n    return enc\n\ntok = AutoTokenizer.from_pretrained(\"microsoft/deberta-v3-base\")\nner_net = AutoModelForTokenClassification.from_pretrained(\"microsoft/deberta-v3-base\", num_labels=7)\n",
  "./code/recipes/procrustes_lib.py": "import numpy as np\nfrom scipy.linalg import orthogonal_procrustes\n\ndef align_embeddings_scipy(corrupted_x: np.ndarray, clean_y: np.ndarray) -> np.ndarray:\n    \"\"\"Giải bài toán sửa chữa không gian nhúng (IOAI 2025 Broken BERT) bằng 2 dòng scipy.linalg.\"\"\"\n    mx, my = corrupted_x.mean(0, keepdims=True), clean_y.mean(0, keepdims=True)\n    omega, _ = orthogonal_procrustes(corrupted_x - mx, clean_y - my)\n    return (corrupted_x - mx) @ omega + my\n",
  "./code/recipes/qa_window_lib.py": "from transformers import AutoModelForQuestionAnswering, AutoTokenizer\n\ndef tokenize_qa_pairs(tok, question: str, context: str, max_len: int = 384, stride: int = 128):\n    \"\"\"Chỉ trượt cửa sổ trên phần ngữ cảnh (only_second), giữ nguyên câu hỏi ở đầu mọi cửa sổ.\"\"\"\n    return tok(\n        question, context, max_length=max_len, stride=stride,\n        truncation=\"only_second\", return_overflowing_tokens=True, return_offsets_mapping=True,\n    )\n\nqa_tok = AutoTokenizer.from_pretrained(\"deepset/xlm-roberta-base-squad2\")\nqa_net = AutoModelForQuestionAnswering.from_pretrained(\"deepset/xlm-roberta-base-squad2\")\n",
  "./code/recipes/rag_reader_lib.py": "from transformers import AutoModelForMultipleChoice, AutoModelForSequenceClassification, AutoTokenizer\n\n# 1. Đầu đọc trắc nghiệm khoa học / pháp luật có ngữ cảnh (chuẩn Top Kaggle LLM Science Exam):\nmc_tok = AutoTokenizer.from_pretrained(\"microsoft/deberta-v3-base\")\nmc_net = AutoModelForMultipleChoice.from_pretrained(\"microsoft/deberta-v3-base\")\n\n# 2. Mô hình suy luận ngôn ngữ tự nhiên (NLI) kiểm chứng câu trả lời có bám sát bằng chứng hay không:\nnli_tok = AutoTokenizer.from_pretrained(\"MoritzLaurer/DeBERTa-v3-base-mnli-fever-anli\")\nnli_net = AutoModelForSequenceClassification.from_pretrained(\"MoritzLaurer/DeBERTa-v3-base-mnli-fever-anli\")\n",
  "./code/recipes/seq2seq_lib.py": "from transformers import AutoModelForSeq2SeqLM, AutoTokenizer, GenerationConfig\n\n# Sinh chuỗi Seq2Seq (BART / Flan-T5 / ViT5) tích hợp sẵn KV-Cache, phạt độ dài & chặn lặp 3-gram:\ns2s_tok = AutoTokenizer.from_pretrained(\"facebook/bart-large-cnn\")\ns2s_net = AutoModelForSeq2SeqLM.from_pretrained(\"facebook/bart-large-cnn\")\ngen_cfg = GenerationConfig(\n    max_new_tokens=140, min_new_tokens=35, num_beams=4,\n    length_penalty=2.0, no_repeat_ngram_size=3, early_stopping=True, use_cache=True,\n)\n",
  "./code/recipes/sliding_window_lib.py": "from transformers import AutoTokenizer\n\ndef sliding_window_tokenize(tok, text: str, max_len: int = 512, stride: int = 128):\n    \"\"\"Cắt tài liệu dài hàng nghìn từ thành các cửa sổ chồng lấp kèm offset_mapping bằng transformers chuẩn.\"\"\"\n    return tok(\n        text, max_length=max_len, stride=stride, truncation=True,\n        return_overflowing_tokens=True, return_offsets_mapping=True,\n    )\n",
  "./code/recipes/tapt_lib.py": "from transformers import (\n    AutoModelForMaskedLM,\n    AutoModelForSequenceClassification,\n    AutoTokenizer,\n    DataCollatorForLanguageModeling,\n)\n\ndef build_tapt_and_classifier(model_name: str = \"FacebookAI/xlm-roberta-base\", num_labels: int = 3):\n    \"\"\"Khởi tạo cặp mô hình Tiền huấn luyện thích nghi miền (TAPT MLM) -> Phân loại dùng chung mọi họ Encoder.\"\"\"\n    tok = AutoTokenizer.from_pretrained(model_name)\n    mlm_collator = DataCollatorForLanguageModeling(tok, mlm=True, mlm_probability=0.15)\n    mlm_net = AutoModelForMaskedLM.from_pretrained(model_name)\n    clf_net = AutoModelForSequenceClassification.from_pretrained(model_name, num_labels=num_labels)\n    # Sau khi train mlm_net vài epoch trên tập văn bản đề thi, chép trọng số sang clf_net bằng base_model:\n    clf_net.base_model.load_state_dict(mlm_net.base_model.state_dict(), strict=False)\n    return tok, mlm_collator, mlm_net, clf_net\n",
  "./code/recipes/tune_th_lib.py": "import numpy as np\nfrom scipy.optimize import minimize\nfrom sklearn.metrics import f1_score\n\ndef tune_thresholds(oof_probs: np.ndarray, y_true: np.ndarray, metric_fn=f1_score) -> np.ndarray:\n    \"\"\"Tối ưu ngưỡng quyết định tổng quát cho mọi độ đo rời rạc (F1, F-beta, MCC) bằng Powell của SciPy.\"\"\"\n    if oof_probs.ndim == 1:\n        oof_probs, y_true = oof_probs[:, None], y_true[:, None]\n    ths = np.full(oof_probs.shape[1], 0.5)\n    for j in range(oof_probs.shape[1]):\n        loss_fn = lambda t: -float(metric_fn(y_true[:, j], (oof_probs[:, j] >= np.clip(t[0], 0.05, 0.95)).astype(int)))\n        ths[j] = np.clip(minimize(loss_fn, x0=[0.5], method=\"Powell\").x[0], 0.05, 0.95)\n    return ths\n",
  "./code/recipes/tuple_seq2seq_lib.py": "from transformers import AutoModelForSeq2SeqLM, AutoTokenizer\n\ndef linearize_tuples(items: list[tuple[str, ...]], tags: tuple[str, ...] = (\"[A]\", \"[C]\", \"[O]\", \"[S]\")) -> str:\n    \"\"\"Hàm tổng quát biến mọi bộ quan hệ (Cặp 2, Bộ 3 ASTE, Bộ 4 ACOS) thành chuỗi đích chuẩn hóa cho T5 / ViT5.\"\"\"\n    return \" ; \".join(\" \".join(f\"{t} {v}\" for t, v in zip(tags, tup)) for tup in items)\n\nt5_tok = AutoTokenizer.from_pretrained(\"google/flan-t5-base\")\nt5_net = AutoModelForSeq2SeqLM.from_pretrained(\"google/flan-t5-base\")\n",
  "./code/recipes/unicode_ood_lib.py": "import re\nimport unicodedata\nimport numpy as np\nfrom sklearn.covariance import LedoitWolf\n\nZERO_WIDTH_RE = re.compile(r\"[\\u200b-\\u200f\\u202a-\\u202e\\u2060\\ufeff]\")\n\ndef clean_unicode(text: str) -> str:\n    \"\"\"Chuẩn hóa NFKC + xóa ký tự tàng hình Zero-Width trong 2 dòng bằng thư viện chuẩn Python.\"\"\"\n    return ZERO_WIDTH_RE.sub(\"\", unicodedata.normalize(\"NFKC\", text))\n\ndef fit_mahalanobis_ood(in_dist_feats: np.ndarray) -> tuple[np.ndarray, np.ndarray]:\n    \"\"\"Ước lượng tâm và nghịch đảo hiệp phương sai co rút Ledoit-Wolf để bắt mẫu lạ OOD.\"\"\"\n    est = LedoitWolf().fit(in_dist_feats)\n    return est.location_, est.precision_\n"
};
